import { InngestTestEngine } from "@inngest/test";
import type { AgentPhoneNumber } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";
import { beforeEach, describe, expect, it, vi } from "vitest";
import {
  createInboundRoutingDispatchRule,
  createInboundTrunk,
  deleteInboundDispatchRule,
  deleteInboundTrunk,
  deleteOutboundTrunk,
} from "@/server/libs/agent-phone-numbers";
import { configureAgentPhoneNumber } from "./configure-agent-phone-number";

// Mock the database
vi.mock("@purplefish-ai/db/server", () => ({
  db: {
    agentPhoneNumber: {
      findUniqueOrThrow: vi.fn(),
      update: vi.fn(),
    },
  },
}));

// Mock the agent phone number functions
vi.mock("@/server/libs/agent-phone-numbers", () => ({
  createInboundRoutingDispatchRule: vi.fn(),
  createInboundTrunk: vi.fn(),
  deleteInboundDispatchRule: vi.fn(),
  deleteInboundTrunk: vi.fn(),
  deleteOutboundTrunk: vi.fn(),
}));

// Helper to create a mock AgentPhoneNumber with all required fields
function createMockAgentPhoneNumber(
  overrides: Partial<AgentPhoneNumber> = {},
): AgentPhoneNumber {
  const now = new Date();
  return {
    id: "agent-phone-123",
    createdAt: now,
    updatedAt: now,
    assignedAt: null,
    number: "+14155551234",
    organizationId: null,
    sipOutboundTrunkId: null,
    sipInboundTrunkId: null,
    sipInboundDispatchRuleId: null,
    sipOutboundTrunkForInboundId: null,
    telnyxPhoneNumberId: null,
    ...overrides,
  } as AgentPhoneNumber;
}

// Helper to create a mock trunk that only includes the properties we actually use
