import { InngestTestEngine } from "@inngest/test";
import type { AgentPhoneNumber } from "@purplefish-ai/db";
import { db } from "@purplefish-ai/db/server";
import { beforeEach, describe, expect, it, vi } from "vitest";
import {
  createInboundRoutingDispatchRule,
  createInboundTrunk,
  deleteInboundDispatchRule,
  deleteInboundTrunk,
  deleteOutboundTrunk,
} from "@/server/libs/agent-phone-numbers";
import { configureAgentPhoneNumber } from "./configure-agent-phone-number";

// Mock the database
vi.mock("@purplefish-ai/db/server", () => ({
  db: {
    agentPhoneNumber: {
      findUniqueOrThrow: vi.fn(),
      update: vi.fn(),
    },
  },
}));

// Mock the agent phone number functions
vi.mock("@/server/libs/agent-phone-numbers", () => ({
  createInboundRoutingDispatchRule: vi.fn(),
  createInboundTrunk: vi.fn(),
  deleteInboundDispatchRule: vi.fn(),
  deleteInboundTrunk: vi.fn(),
  deleteOutboundTrunk: vi.fn(),
}));

// Helper to create a mock AgentPhoneNumber with all required fields
function createMockAgentPhoneNumber(
  overrides: Partial<AgentPhoneNumber> = {},
): AgentPhoneNumber {
  const now = new Date();
  return {
    id: "agent-phone-123",
    createdAt: now,
    updatedAt: now,
    assignedAt: null,
    number: "+14155551234",
    organizationId: null,
    sipOutboundTrunkId: null,
    sipInboundTrunkId: null,
    sipInboundDispatchRuleId: null,
    sipOutboundTrunkForInboundId: null,
    telnyxPhoneNumberId: null,
    ...overrides,
  } as AgentPhoneNumber;
}

// Helper to create a mock trunk that only includes the properties we actually use
function createMockTrunk(sipTrunkId: string) {
  return {
    sipTrunkId,
  } as unknown as Awaited<ReturnType<typeof createInboundTrunk>>;
}

// Helper to create a mock dispatch rule that only includes the properties we actually use
function createMockDispatchRule(sipDispatchRuleId: string) {
  return {
    sipDispatchRuleId,
  } as unknown as Awaited<ReturnType<typeof createInboundRoutingDispatchRule>>;
}

describe("configureAgentPhoneNumber", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("should configure a new agent phone number without existing trunk IDs", async () => {
    const mockPhoneNumber = "+14155551234";
    const mockAgentPhoneNumber = createMockAgentPhoneNumber({
      number: mockPhoneNumber,
      sipInboundTrunkId: null,
      sipInboundDispatchRuleId: null,
      sipOutboundTrunkId: null,
    });

    const mockTrunk = createMockTrunk("trunk-456");
    const mockDispatchRule = createMockDispatchRule("dispatch-789");

    const expectedUpdateResult = createMockAgentPhoneNumber({
      ...mockAgentPhoneNumber,
      sipInboundTrunkId: mockTrunk.sipTrunkId,
      sipInboundDispatchRuleId: mockDispatchRule.sipDispatchRuleId,
      sipOutboundTrunkId: mockTrunk.sipTrunkId,
    });

    // Setup mocks with proper types
    vi.mocked(db.agentPhoneNumber.findUniqueOrThrow).mockResolvedValue(
      mockAgentPhoneNumber,
    );
    vi.mocked(createInboundTrunk).mockResolvedValue(mockTrunk);
    vi.mocked(createInboundRoutingDispatchRule).mockResolvedValue(
      mockDispatchRule,
    );
    vi.mocked(db.agentPhoneNumber.update).mockResolvedValue(
      expectedUpdateResult,
    );

    // Create test engine with transformCtx to properly pass event data
    const testEngine = new InngestTestEngine({
      function: configureAgentPhoneNumber,
      transformCtx: (ctx) => ({
        ...ctx,
        event: {
          ...ctx.event,
          name: "configure.agent-phone-number.triggered",
          data: {
            phoneNumber: mockPhoneNumber,
          },
        },
      }),
    });

    // Execute the function
    const { result } = await testEngine.execute();

    // Assertions
    expect(db.agentPhoneNumber.findUniqueOrThrow).toHaveBeenCalledWith({
      where: {
        number: mockPhoneNumber,
      },
    });

    expect(deleteInboundTrunk).not.toHaveBeenCalled();
    expect(deleteInboundDispatchRule).not.toHaveBeenCalled();
    expect(deleteOutboundTrunk).not.toHaveBeenCalled();

    expect(createInboundTrunk).toHaveBeenCalledWith({
      number: mockPhoneNumber,
    });

    expect(createInboundRoutingDispatchRule).toHaveBeenCalledWith({
      sipInboundTrunkId: mockTrunk.sipTrunkId,
      number: mockPhoneNumber,
    });

    expect(db.agentPhoneNumber.update).toHaveBeenCalledWith({
      where: {
        id: mockAgentPhoneNumber.id,
      },
      data: {
        sipInboundTrunkId: mockTrunk.sipTrunkId,
        sipInboundDispatchRuleId: mockDispatchRule.sipDispatchRuleId,
        sipOutboundTrunkId: mockTrunk.sipTrunkId,
      },
    });

    expect(result).toEqual(expectedUpdateResult);
  });

  it("should delete existing trunk configurations before creating new ones", async () => {
    const mockPhoneNumber = "+14155551234";
    const mockAgentPhoneNumber = createMockAgentPhoneNumber({
      number: mockPhoneNumber,
      sipInboundTrunkId: "old-trunk-111",
      sipInboundDispatchRuleId: "old-dispatch-222",
      sipOutboundTrunkId: "old-outbound-333",
    });

    const mockTrunk = createMockTrunk("new-trunk-456");
    const mockDispatchRule = createMockDispatchRule("new-dispatch-789");

    const expectedUpdateResult = createMockAgentPhoneNumber({
      ...mockAgentPhoneNumber,
      sipInboundTrunkId: mockTrunk.sipTrunkId,
      sipInboundDispatchRuleId: mockDispatchRule.sipDispatchRuleId,
      sipOutboundTrunkId: mockTrunk.sipTrunkId,
    });

    // Setup mocks
    vi.mocked(db.agentPhoneNumber.findUniqueOrThrow).mockResolvedValue(
      mockAgentPhoneNumber,
    );
    vi.mocked(createInboundTrunk).mockResolvedValue(mockTrunk);
    vi.mocked(createInboundRoutingDispatchRule).mockResolvedValue(
      mockDispatchRule,
    );
    vi.mocked(db.agentPhoneNumber.update).mockResolvedValue(
      expectedUpdateResult,
    );

    // Create test engine
    const testEngine = new InngestTestEngine({
      function: configureAgentPhoneNumber,
      transformCtx: (ctx) => ({
        ...ctx,
        event: {
          ...ctx.event,
          name: "configure.agent-phone-number.triggered",
          data: {
            phoneNumber: mockPhoneNumber,
          },
        },
      }),
    });

    // Execute the function
    const { result } = await testEngine.execute();

    // Assertions - verify delete functions were called
    expect(deleteInboundTrunk).toHaveBeenCalledWith(mockAgentPhoneNumber.id);
    expect(deleteInboundDispatchRule).toHaveBeenCalledWith(
      mockAgentPhoneNumber.id,
    );
    expect(deleteOutboundTrunk).toHaveBeenCalledWith(mockAgentPhoneNumber.id);

    // Verify creation and update still happened
    expect(createInboundTrunk).toHaveBeenCalledWith({
      number: mockPhoneNumber,
    });

    expect(createInboundRoutingDispatchRule).toHaveBeenCalledWith({
      sipInboundTrunkId: mockTrunk.sipTrunkId,
      number: mockPhoneNumber,
    });

    expect(result).toEqual(expectedUpdateResult);
  });

  it("should handle partial existing trunk configurations", async () => {
    const mockPhoneNumber = "+14155551234";
    const mockAgentPhoneNumber = createMockAgentPhoneNumber({
      number: mockPhoneNumber,
      sipInboundTrunkId: "old-trunk-111",
      sipInboundDispatchRuleId: null,
      sipOutboundTrunkId: null,
    });

    const mockTrunk = createMockTrunk("new-trunk-456");
    const mockDispatchRule = createMockDispatchRule("new-dispatch-789");

    const mockUpdateResult = createMockAgentPhoneNumber({
      ...mockAgentPhoneNumber,
      sipInboundTrunkId: mockTrunk.sipTrunkId,
      sipInboundDispatchRuleId: mockDispatchRule.sipDispatchRuleId,
      sipOutboundTrunkId: mockTrunk.sipTrunkId,
    });

    // Setup mocks
    vi.mocked(db.agentPhoneNumber.findUniqueOrThrow).mockResolvedValue(
      mockAgentPhoneNumber,
    );
    vi.mocked(createInboundTrunk).mockResolvedValue(mockTrunk);
    vi.mocked(createInboundRoutingDispatchRule).mockResolvedValue(
      mockDispatchRule,
    );
    vi.mocked(db.agentPhoneNumber.update).mockResolvedValue(mockUpdateResult);

    // Create test engine
    const testEngine = new InngestTestEngine({
      function: configureAgentPhoneNumber,
      transformCtx: (ctx) => ({
        ...ctx,
        event: {
